"""College hub: roadmap, applications, essays, financial aid, scholarships, majors & careers."""
from kit import page, article, faq, ad, lead_band, page_hero, mini_lead, e
from subjects import vids

LINKS = [("4-Year Roadmap", "@@/college/roadmap/"), ("Applications", "@@/college/applications/"), ("College Essays", "@@/college/essays/"), ("Financial Aid & FAFSA", "@@/college/financial-aid/"),
         ("Scholarships", "@@/college/scholarships/"), ("Majors & Careers", "@@/college/majors-careers/"), ("College Cost Calculator", "@@/tools/college-cost-calculator/")]


def A(path, title, h1, desc, name, body, kw, faqs=None, need="College counseling", tools=False):
    crumbs = [("College", "@@/college/"), (name, "")]
    schema = []
    if faqs:
        fq, fs = faq(faqs); body += fq; schema.append(fs)
    html = article(h1, desc, crumbs, body, LINKS, name, need, eyebrow="College & Beyond")
    page(path, title, desc, html + lead_band("Get a free college-planning match", "College counselors, essay coaches and scholarship resources matched to your grade, goals and budget.", need), crumbs, schema, kw, tools=tools)


ROAD = {
    "9th grade — Foundation": ["Meet your school counselor and learn graduation requirements", "Build strong study habits from day one", "Try 2–3 clubs, sports or activities", "Start a simple “brag sheet” of awards and activities", "Read for fun every week", "Explore summer programs, jobs or volunteering"],
    "10th grade — Explore": ["Take the most rigorous courses you can succeed in", "Take the PSAT 10 or a practice SAT/ACT", "Go deeper in 1–2 activities; seek a leadership role", "Explore careers and possible majors", "Visit a nearby college campus (even virtually)", "Plan a meaningful summer"],
    "11th grade — Build": ["Take the PSAT/NMSQT in October", "Take the SAT or ACT in winter/spring", "Take AP/IB/dual-enrollment courses in your strengths", "Build a balanced college list (reach / target / likely)", "Ask two teachers for recommendation letters in spring", "Draft your personal statement over the summer"],
    "12th grade — Launch": ["Finalize your college list and deadlines", "Submit FAFSA (opens October 1) and CSS Profile if required", "Submit early applications (Nov 1/15) if applying early", "Submit regular applications (often Jan 1–15)", "Apply for scholarships every month", "Compare aid offers and decide by May 1"],
}


def build():
    # Roadmap (interactive checklist)
    cols = ""
    for gi, (g, items) in enumerate(ROAD.items()):
        boxes = "".join(f'<label><input type="checkbox" data-key="g{gi}i{ii}"> <span>{e(t)}</span></label>' for ii, t in enumerate(items))
        cols += f'<div class="grade"><h3>{e(g)}</h3><div class="meter"><i></i></div><p class="small muted"><span class="cnt">0/0</span> done</p>{boxes}</div>'
    body = f'''<p>Getting into college and graduating with options isn’t about one big moment in senior year — it’s dozens of small steps across four years. Check items off below; your progress is saved privately on this device.</p>
<div id="roadmap-tool" class="roadmap" style="margin:24px 0">{cols}</div>
<h2>Why a roadmap beats cramming senior year</h2><p>Colleges read your transcript across all four years, and many opportunities — National Merit (11th-grade PSAT), summer programs, leadership roles — have early deadlines. Students who plan ahead take the right courses at the right time and keep senior fall free for applications instead of catching up.</p>
<h2>For parents</h2><p>Your role shifts each year: in 9th grade, help build habits and explore; in 10th–11th, help research options and budget; in 12th, support deadlines and financial aid paperwork. See our <a href="@@/guides/parent-guide/">Parent Guide</a> and the <a href="@@/tools/college-cost-calculator/">college cost calculator</a>.</p>
<h2>Not planning on a four-year college?</h2><p>The same roadmap works for community college, apprenticeships, the military or trade school — swap campus visits for program visits and apprenticeship applications. Explore <a href="@@/college/majors-careers/">majors & careers</a>.</p>'''
    A("college/roadmap/", "High School to College Roadmap: Grade 9–12 Checklist", "🗺️ The 4-Year High School Roadmap", "An interactive grade-by-grade checklist from 9th to 12th grade: classes, tests, activities, college lists, applications and financial aid.", "4-Year Roadmap", body, "college planning timeline, high school checklist, college prep by grade", [
        ("When should I start preparing for college?", "Ninth grade — not with stress, but with good grades, exploring activities and knowing your graduation requirements. Most heavy lifting happens in 11th and 12th grade."),
        ("Is it too late to start in 11th grade?", "Not at all. Focus on strong junior-year grades, testing if needed, and a well-researched college list. Many students do most of their planning in 11th grade.")], tools=True)

    A("college/applications/", "College Application Guide: Timeline, ED vs EA & Checklist", "📮 How to Apply to College", "A step-by-step college application guide: building your list, Early Decision vs Early Action, Common App, recommendations, deadlines and a submission checklist.", "Applications", f'''
<p>Most US students apply to 6–12 colleges through a platform like the <strong>Common App</strong> (opens August 1), the Coalition application, or a college’s own portal. A strong application tells one consistent story: your transcript, activities, essays and recommendations should all reinforce who you are and what you care about.</p>
<h2>Build a balanced list</h2><ul><li><strong>Reach (2–3):</strong> your stats are below the college’s middle 50%, or admit rates are very low.</li><li><strong>Target (3–5):</strong> your GPA and scores fall inside the middle 50%.</li><li><strong>Likely (2–3):</strong> your stats are above the range <em>and</em> you can afford it after aid.</li></ul>
<h2>Application rounds</h2><table><thead><tr><th>Round</th><th>Typical deadline</th><th>Binding?</th></tr></thead><tbody><tr><td>Early Decision (ED I)</td><td>Nov 1–15</td><td>Yes — you must attend if admitted with adequate aid</td></tr><tr><td>Early Action (EA)</td><td>Nov 1–15</td><td>No</td></tr><tr><td>Restrictive Early Action (REA)</td><td>Nov 1</td><td>No, but limits other early applications</td></tr><tr><td>Early Decision II</td><td>Jan 1–15</td><td>Yes</td></tr><tr><td>Regular Decision</td><td>Jan 1–Feb 1</td><td>No</td></tr><tr><td>Rolling</td><td>Until full</td><td>No</td></tr></tbody></table>
<p>National College Decision Day is <strong>May 1</strong>, when most colleges ask admitted students to commit.</p>
{ad()}
<h2>Application checklist</h2><ol><li>Personal information and family details</li><li>Transcript requested from your counselor</li><li>Test scores (if submitting) — official reports or self-reported, per college policy</li><li>Activities list (up to 10 on the Common App) — lead with impact and numbers</li><li>Personal statement (650 words max on the Common App) — see <a href="@@/college/essays/">essay guide</a></li><li>Supplemental essays (“Why us?”, community, intellectual interest)</li><li>Two teacher recommendations + counselor recommendation (ask by spring of junior year)</li><li>Application fee or fee waiver</li><li>FAFSA and CSS Profile for aid</li></ol>
<div class="callout v"><p><strong>Fee waivers:</strong> students who qualify for SAT/ACT fee waivers or free/reduced lunch can usually apply to colleges for free. Ask your counselor.</p></div>''', "college application, early decision vs early action, common app, application checklist", [
        ("How many colleges should I apply to?", "Most students apply to 6–12. The key is balance: every school on your list should be one you’d be happy to attend and could afford."),
        ("Should I apply Early Decision?", "Only if a college is your clear first choice and you’ve used its Net Price Calculator to confirm the cost works, since ED is binding.")])

    A("college/essays/", "How to Write a College Essay: Personal Statement Guide", "✍️ How to Write a Standout College Essay", "A practical guide to the college personal statement: choosing a topic, structure, show-don’t-tell, revision, the 650-word limit and common mistakes.", "College Essays", f'''
<p>The personal statement is the one part of your application entirely in your voice. Admissions readers spend only a few minutes on it, so the goal isn’t to sound impressive — it’s to be <strong>specific, honest and memorable</strong>. The Common App limits it to <strong>650 words</strong>.</p>
<h2>Step 1 — Find your topic</h2><p>Great essays rarely come from “big” topics. Brainstorm: values you live by, small daily rituals, objects that matter, problems you’ve obsessed over, ways you’ve changed. A good test: <em>could only you have written this?</em></p>
<h2>Step 2 — Choose a structure</h2><ul><li><strong>Narrative:</strong> a challenge or turning point → what you did → how you changed.</li><li><strong>Montage:</strong> several small moments linked by a common thread (an object, a value, a recurring image).</li></ul>
<h2>Step 3 — Show, don’t tell</h2><p>Instead of “I am resilient,” show the 6 a.m. alarm, the third failed attempt, the moment you tried a new approach. Then reflect: what does it say about how you think?</p>
{ad()}
<h2>Step 4 — Revise in passes</h2><ol><li><strong>Big picture:</strong> is the insight clear? Is at least a third of the essay reflection?</li><li><strong>Paragraphs:</strong> does every paragraph move the story forward?</li><li><strong>Sentences:</strong> cut filler (“very,” “really,” “in order to”), use active verbs.</li><li><strong>Proofread aloud</strong> — and have one trusted reader, not ten.</li></ol>
<h2>Common mistakes</h2><ul><li>Repeating your activities list in paragraph form.</li><li>Writing about someone else (a grandparent, a coach) more than yourself.</li><li>A thesaurus voice that doesn’t sound like you.</li><li>Ending with a cliché (“…and that’s when I realized hard work pays off”).</li></ul>
<div class="callout"><p>On AI tools: many colleges ask applicants to certify the work is their own. Use tools for brainstorming questions or grammar checks if your colleges permit it — but the ideas and words should be yours.</p></div>
<h2>Watch</h2>{vids(["essay", "essay2"])}''', "college essay, personal statement, common app essay, how to write a college essay", [
        ("How long should my college essay be?", "Use most of the limit — for the Common App, aim for 550–650 words. Supplemental essays have their own limits."),
        ("Can I write about a sad or hard topic?", "Yes, if the focus is on your reflection and growth rather than only the event. You choose what to share."),
        ("When should I start my essay?", "The summer before senior year is ideal — it leaves time for several drafts before fall deadlines.")])

    A("college/financial-aid/", "Financial Aid & FAFSA Guide for High School Families", "💵 Financial Aid & the FAFSA, Explained", "How college financial aid works: the FAFSA, the Student Aid Index, grants, scholarships, work-study, loans, the CSS Profile and comparing aid offers.", "Financial Aid & FAFSA", f'''
<p>The sticker price of college is rarely what families actually pay. Grants, scholarships and other aid can cut the cost dramatically — but only if you apply. The single most important step is the <strong>FAFSA</strong> (Free Application for Federal Student Aid), which typically opens <strong>October 1</strong> for the following school year at <a href="https://studentaid.gov/" target="_blank" rel="noopener">StudentAid.gov</a>.</p>
<h2>Types of aid</h2><table><thead><tr><th>Type</th><th>Repay?</th><th>Examples</th></tr></thead><tbody><tr><td>Grants</td><td>No</td><td>Federal Pell Grant, state grants, college grants</td></tr><tr><td>Scholarships</td><td>No</td><td>Merit, need-based, private/community scholarships</td></tr><tr><td>Work-study</td><td>No (you earn it)</td><td>Part-time campus jobs</td></tr><tr><td>Federal loans</td><td>Yes</td><td>Direct Subsidized/Unsubsidized loans, Parent PLUS</td></tr><tr><td>Private loans</td><td>Yes</td><td>Banks and lenders — usually a last resort</td></tr></tbody></table>
<h2>How the FAFSA works</h2><ol><li>Student and each required contributor (usually parents) create a StudentAid.gov account.</li><li>Complete the form; contributors give consent to import federal tax information.</li><li>List every college you’re considering (you can add more later).</li><li>You’ll receive a <strong>FAFSA Submission Summary</strong> with your <strong>Student Aid Index (SAI)</strong> — the number colleges use to calculate need.</li><li>Colleges send aid offers after admission.</li></ol>
{ad()}
<h2>The CSS Profile</h2><p>Several hundred mostly private colleges also require the CSS Profile for their own institutional aid. It asks for more detail than the FAFSA. Check each college’s financial aid page.</p>
<h2>Comparing aid offers</h2><p>Line up each offer by <strong>net cost = cost of attendance − grants and scholarships</strong>. Loans and work-study are not discounts. If an offer seems low, you can appeal with new information (job loss, medical costs, a better offer elsewhere).</p>
<p>Plan ahead with our <a href="@@/tools/college-cost-calculator/">college cost calculator</a> and stack free money with our <a href="@@/college/scholarships/">scholarship tracker</a>.</p><p class="small muted">Educational information only, not financial advice. Rules change — confirm on StudentAid.gov and with each college.</p>''', "fafsa, financial aid, student aid index, css profile, pell grant, compare aid offers", [
        ("When should I file the FAFSA?", "As early as possible after it opens (normally October 1). Some state and college aid is first-come, first-served."),
        ("Do I need to file the FAFSA if my family earns too much?", "Usually yes. Many colleges require it for merit scholarships and it’s the only way to access federal student loans."),
        ("What is the Student Aid Index?", "The SAI is an eligibility index calculated from your FAFSA. Colleges use it to determine need-based aid. It can be negative (down to −1,500).")])

    # Scholarships with tracker + alerts form
    body = f'''<p>Scholarships are free money for college that you don’t repay. They come from colleges, companies, foundations, community groups and governments. The students who win the most aren’t always top of the class — they’re the ones who apply <strong>consistently</strong>, including to small local awards with fewer applicants.</p>
<h2>Your scholarship tracker</h2><p>Add every scholarship you find. We’ll sort by deadline and show days remaining. Saved privately on this device.</p>
<div class="tool" id="sch-tool"><form id="sch-form" class="grid g4" style="align-items:end"><div class="field"><label for="sch-n">Scholarship name</label><input id="sch-n" type="text" required></div><div class="field"><label for="sch-a">Amount ($)</label><input id="sch-a" type="number" min="0" required></div><div class="field"><label for="sch-d">Deadline</label><input id="sch-d" type="date"></div><button class="btn btn-primary" type="submit">+ Add</button></form>
<div style="overflow-x:auto;margin-top:12px"><table><thead><tr><th>Name</th><th>Amount</th><th>Deadline</th><th>Status</th><th></th></tr></thead><tbody id="sch-rows"></tbody></table></div>
<div class="result"><div><b id="sch-count">0</b><span>Tracked</span></div><div><b id="sch-total">$0</b><span>Potential</span></div><div><b id="sch-won">$0</b><span>Won</span></div></div></div>
<h2 id="alerts">Get scholarship alerts</h2><div class="card"><form class="form" data-form data-thanks="thank-you/"><input type="hidden" name="_subject" value="New High.School lead — Scholarship alerts"><input type="hidden" name="I need" value="Scholarship alerts"><input class="hp" type="text" name="_honey" tabindex="-1" autocomplete="off" aria-hidden="true">
<div class="row2"><div class="field"><label for="sa-grad">Graduation year</label><select id="sa-grad" name="Graduation year" required><option value="">Choose…</option><option>2027</option><option>2028</option><option>2029</option><option>2030</option><option>Already graduated / adult learner</option></select></div><div class="field"><label for="sa-state">State / province / country</label><input id="sa-state" type="text" name="Location" required></div></div>
<div class="row2"><div class="field"><label for="sa-major">Intended major or interest</label><input id="sa-major" type="text" name="Intended major" placeholder="e.g. nursing, engineering, undecided"></div><div class="field"><label for="sa-gpa">GPA range</label><select id="sa-gpa" name="GPA range"><option>Prefer not to say</option><option>3.8+</option><option>3.5–3.79</option><option>3.0–3.49</option><option>2.5–2.99</option><option>Below 2.5</option></select></div></div>
<div class="row2"><div class="field"><label for="sa-name">First name</label><input id="sa-name" type="text" name="Name" required></div><div class="field"><label for="sa-email">Email</label><input id="sa-email" type="email" name="Email" required></div></div>
<div class="field"><label for="sa-role">I am</label><select id="sa-role" name="I am" required><option value="">Choose…</option><option>Student 13–17</option><option>Parent / guardian</option><option>Adult learner 18+</option><option>Under 13</option></select></div>
<p class="small muted">What you’ll get: new matches about once a week, plus deadline reminders. No spam, unsubscribe anytime.</p>
<label class="check"><input type="checkbox" name="Consent" value="Yes" required><span>Send me scholarship alerts. If I’m under 18, a parent/guardian has approved this.</span></label>
<button class="btn btn-primary" type="submit">Check for scholarships</button><p class="form-status" aria-live="polite"></p></form></div>
{ad()}
<h2>Where to find scholarships</h2><ul><li><strong>Your colleges:</strong> merit scholarships are often automatic with admission; check each college’s aid page.</li><li><strong>Your school counselor’s list:</strong> local awards from businesses, credit unions and civic clubs.</li><li><strong>Your state:</strong> many states fund merit and need-based grants.</li><li><strong>Employers and unions:</strong> parents’ employers often sponsor awards.</li><li><strong>Identity and interest groups:</strong> heritage, faith, first-generation, major-specific, athletic and arts organizations.</li><li><strong>Free national search sites</strong> — never pay to apply or to “guarantee” a scholarship.</li></ul>
<h2>How to win more</h2><ol><li>Apply monthly from junior year onward.</li><li>Keep a master essay bank and adapt it — many prompts overlap.</li><li>Follow instructions exactly; incomplete applications are discarded first.</li><li>Ask for recommendation letters early and send thank-you notes.</li></ol>
<div class="callout"><p><strong>Scam warning:</strong> legitimate scholarships never charge application fees or ask for bank details to “release” an award.</p></div>
<p>Students can also enter High.School’s own <a href="@@/contests/">contests</a>.</p>'''
    A("college/scholarships/", "Scholarships for High School Students: Find, Track & Win", "🏆 Scholarships: Find, Track & Win", "How to find and win scholarships in high school — a free deadline tracker, scholarship alerts, where to search, how to win more and how to spot scams.", "Scholarships", body, "scholarships for high school students, scholarship tracker, scholarships for seniors, no essay scholarships", [
        ("When should I start applying for scholarships?", "Some scholarships accept students as young as 9th grade, but most open in junior and senior year. Start tracking in 11th grade and apply monthly."),
        ("Are scholarship search sites legit?", "Reputable search sites are free. Never pay a fee to apply for a scholarship or for a service that guarantees awards."),
        ("Do small scholarships matter?", "Yes. $500–$1,000 local awards have fewer applicants, so your odds are higher — and they add up.")], need="Scholarship alerts", tools=True)

    A("college/majors-careers/", "Majors & Careers: How to Choose a Path in High School", "🧭 Majors & Careers: Find Your Direction", "How to explore majors and careers in high school: interest inventories, career clusters, what to take now, job shadowing, and paths beyond four-year college.", "Majors & Careers", f'''
<p>You don’t need to know your career at 15. But exploring early helps you pick courses, activities and summer experiences with purpose — and many students change direction several times. The goal is to test ideas cheaply now so you make better decisions later.</p>
<h2>A 4-step exploration method</h2><ol><li><strong>Inventory:</strong> list subjects you enjoy, problems you like solving, and how you like to work (with people, data, things, ideas).</li><li><strong>Research:</strong> use the US Bureau of Labor Statistics’ <a href="https://www.bls.gov/ooh/" target="_blank" rel="noopener">Occupational Outlook Handbook</a> for pay, education and growth outlook.</li><li><strong>Test:</strong> job-shadow, volunteer, take an elective, try a summer program or a part-time job.</li><li><strong>Reflect:</strong> what energized you? What drained you? Adjust.</li></ol>
<h2>Career clusters and high school courses</h2><table><thead><tr><th>Cluster</th><th>Take now</th><th>Example paths</th></tr></thead><tbody>
<tr><td>Health science</td><td>Biology, chemistry, anatomy, AP Psych</td><td>Nursing, medicine, physical therapy, health informatics</td></tr>
<tr><td>Engineering & tech</td><td>Calculus, physics, CS</td><td>Software, mechanical, civil, cybersecurity</td></tr>
<tr><td>Business & finance</td><td>Statistics, economics, personal finance</td><td>Accounting, marketing, entrepreneurship</td></tr>
<tr><td>Education & social services</td><td>Psychology, English, languages</td><td>Teaching, counseling, social work</td></tr>
<tr><td>Arts, media & design</td><td>Art, design, journalism, CS</td><td>UX design, film, animation, communications</td></tr>
<tr><td>Skilled trades</td><td>CTE courses, math, physics</td><td>Electrician, HVAC, welding, plumbing (often via apprenticeships)</td></tr></tbody></table>
{ad()}
<h2>Paths beyond a four-year degree</h2><p>Community college (including transfer pathways), apprenticeships (earn while you learn), military service, certificates and trade schools are all strong routes — many skilled trades offer solid pay and demand. The right path is the one that fits your goals and finances.</p>
<h2>Soft skills matter everywhere</h2>{vids(["soft"])}''', "how to choose a major, career exploration for high school students, career clusters", [
        ("Do I need to pick a major when I apply to college?", "Usually not. Many colleges let you apply undecided. Some competitive programs (engineering, nursing) require you to apply directly."),
        ("How do I find job shadowing?", "Ask family, teachers and your counselor; contact local businesses, hospitals and offices politely by email; check your school’s CTE program.")])

    hub = page_hero("College & Beyond", "From your first day of 9th grade to your first day on campus (or on the job): roadmaps, applications, essays, financial aid and scholarships — in plain English.", [("College", "")], eyebrow="Plan · Apply · Pay · Launch")
    cards = [("🗺️", "4-Year Roadmap", "Interactive grade 9–12 checklist.", "roadmap/"), ("📮", "Applications", "Build your list, ED vs EA, checklist.", "applications/"), ("✍️", "College Essays", "Write a personal statement that stands out.", "essays/"),
             ("💵", "Financial Aid & FAFSA", "Grants, loans, SAI and aid offers.", "financial-aid/"), ("🏆", "Scholarships", "Tracker, alerts and how to win.", "scholarships/"), ("🧭", "Majors & Careers", "Explore paths, including beyond college.", "majors-careers/")]
    hub += '<div class="wrap"><section><div class="grid g3">' + "".join(f'<a class="card" href="@@/college/{u}"><div class="ico v">{i}</div><h3>{t}</h3><p>{d}</p></a>' for i, t, d, u in cards) + "</div></section></div>"
    page("college/", "College Planning Hub: Applications, Essays, Aid & Scholarships", "Free college planning for high school students and parents: 4-year roadmap, applications, essays, FAFSA and financial aid, scholarships, majors and careers.", hub + lead_band("Get a free college-counseling match", "Personalized help with college lists, essays and financial aid — matched to your goals and budget.", "College counseling"), [("College", "")], keywords="college planning, college admissions, fafsa, scholarships")
